def solve(grid):
    if not grid:
        return grid

    h = len(grid)
    w = len(grid[0])

    # find the first row that contains any non‑zero value
    base_row = None
    base_items = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                base_row = i
                # collect all non‑zero cells in this row
                for jj in range(w):
                    val = grid[i][jj]
                    if val != 0:
                        base_items.append((jj, val))
                break
        if base_row is not None:
            break

    # create output grid filled with zeros
    out = [[0] * w for _ in range(h)]

    # if there is no non‑zero cell, return the all‑zero grid
    if base_row is None:
        return out

    # fill the grid according to the parity relative to the base row
    for i in range(h):
        if (i - base_row) % 2 == 0:
            # even offset → place original values
            for col, val in base_items:
                out[i][col] = val
        else:
            # odd offset → place values to the left and right
            for col, val in base_items:
                left = col - 1
                right = col + 1
                if left >= 0:
                    out[i][left] = val
                if right < w:
                    out[i][right] = val

    return out

